#pragma once
static const char CLOCK_PAGE[]=R"HTML(<h1>時鐘校對</h1><p>使用臺灣時間。可依手機時間校對，或選擇日期、小時及分鐘。</p><p id="status" role="status"></p><label>日期<input id="date" type="date" min="2024-01-01" max="2099-12-31"></label><div class="time-row"><strong>裝置時間</strong><label>時<select id="hour" aria-label="裝置小時"></select></label><label>分<select id="minute" aria-label="裝置分鐘"></select></label></div><button id="save">套用選擇的時間</button><p><button id="phone" class="secondary">使用此手機時間</button></p><p class="help">每三小時自動網路校時仍會繼續，下一次成功校時將以網路時間為準。</p><a href="/display">返回裝置設定</a><script>
const nonce='NONCE',statusEl=document.querySelector('#status');let dirty=false,sequence=0;for(const id of ['date','hour','minute'])document.getElementById(id).addEventListener('input',()=>{dirty=true;sequence++});for(const [id,count] of [['hour',24],['minute',60]])for(let i=0;i<count;i++){const o=document.createElement('option');o.value=String(i).padStart(2,'0');o.textContent=o.value;document.getElementById(id).append(o)}
function show(epoch){const s=new Date(epoch*1000+8*3600000).toISOString();document.querySelector('#date').value=s.slice(0,10);document.querySelector('#hour').value=s.slice(11,13);document.querySelector('#minute').value=s.slice(14,16)}
async function setClock(epoch){dirty=true;sequence++;for(const id of ['save','phone','date','hour','minute'])document.getElementById(id).disabled=true;try{const r=await fetch('/api/local-clock',{method:'POST',headers:{'X-Setup-Nonce':nonce,'Content-Type':'application/json'},body:JSON.stringify({epoch})});if(!r.ok)throw Error(await r.text());show(epoch);statusEl.textContent='時鐘已更新。'}catch(e){statusEl.textContent='校時失敗：'+e.message}finally{for(const id of ['save','phone','date','hour','minute'])document.getElementById(id).disabled=false}}
document.querySelector('#save').onclick=()=>{const date=document.querySelector('#date').value;if(!date){statusEl.textContent='請先選擇日期。';return}const epoch=Date.parse(date+'T'+document.querySelector('#hour').value+':'+document.querySelector('#minute').value+':00+08:00')/1000;if(Number.isFinite(epoch))setClock(epoch)};document.querySelector('#phone').onclick=()=>setClock(Math.floor(Date.now()/1000));show(Math.floor(Date.now()/1000));const initialSequence=sequence;fetch('/api/status').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{if(dirty||sequence!==initialSequence)return;if(d.clockReady)show(d.epoch);else statusEl.textContent='裝置尚未校時，請選擇正確時間。'}).catch(()=>{if(!dirty&&sequence===initialSequence)statusEl.textContent='無法讀取裝置時鐘，請確認連線。'});
</script>)HTML";
